    /**
     * Method to retrieve the ATM via ATMFetchOneSummary
     * @param 	summary ATMFetchOneSummary 
     * @return 	ATMFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public ATM getATM( ATMFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "ATMFetchOneSummary arg cannot be null" );
    	
    	ATM entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	ATMValidator.getInstance().validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a ATM
        	// --------------------------------------
        	CompletableFuture<ATM> futureEntity = queryGateway.query(new FindATMQuery( new LoadATMFilter( summary.getATMId() ) ), ResponseTypes.instanceOf(ATM.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate ATM with id " + summary.getATMId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


    /**
     * Method to retrieve a collection of all ATMs
     *
     * @return 	List<ATM> 
     * @exception ProcessingException Thrown if any problems
     */
    public List<ATM> getAllATM() 
    throws ProcessingException {
        List<ATM> list = null;

        try {
        	CompletableFuture<List<ATM>> futureList = queryGateway.query(new FindAllATMQuery(), ResponseTypes.multipleInstancesOf(ATM.class));
        	
        	list = futureList.get();
        }
        catch( Exception exc ) {
            String errMsg = "Failed to get all ATM";
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return list;
    }

    /**
     * assign Branch on ATM
     * @param		command AssignBranchToATMCommand	
     * @exception	ProcessingException
     */     
	public void assignBranch( AssignBranchToATMCommand command ) throws ProcessingException {

		// --------------------------------------------
		// load the parent
		// --------------------------------------------
		load( command.getATMId() );
		
		BranchService childDelegate 	= BranchService.getBranchInstance();
		ATMService parentDelegate = ATMService.getATMInstance();			
		UUID childId = command.getAssignment().getBranchId();
		Branch child = null;
		
		try {
			// --------------------------------------
	    	// best to validate the command now
	    	// --------------------------------------    
	    	ATMValidator.getInstance().validate( command );    

	    	// --------------------------------------
        	// issue the command
        	// --------------------------------------    	
    		commandGateway.sendAndWait( command );

		}
        catch( Throwable exc ) {
			final String msg = "Failed to get Branch using id " + childId;
			LOGGER.log( Level.WARNING,  msg );
			throw new ProcessingException( msg, exc );
        }
	}

